35	// CompOp represents a comparison operator.
36	type CompOp string
37	
38	const (
39		// OpEq represents equality (==)
40		OpEq CompOp = "=="
41		// OpNe represents inequality (!=)
42		OpNe CompOp = "!="
43		// OpLt represents less than (<)
44		OpLt CompOp = "<"
45		// OpLe represents less than or equal (<=)
46		OpLe CompOp = "<="
47		// OpGt represents greater than (>)
48		OpGt CompOp = ">"
49		// OpGe represents greater than or equal (>=)
50		OpGe CompOp = ">="
51	)
52	
53	// Comparison represents a comparison between two expressions.
54	type Comparison struct {
55		baseCondition
56		left  Expr
57		op    CompOp
58		right Expr
59	}
60	
61	// Left returns the left-hand side expression.
62	func (c *Comparison) Left() Expr { return c.left }
63	
64	// Op returns the comparison operator.
65	func (c *Comparison) Op() CompOp { return c.op }
66	
67	// Right returns the right-hand side expression.
68	func (c *Comparison) Right() Expr { return c.right }
69	
70	// Eq creates an equality comparison.
71	func Eq(left, right Expr) *Comparison {
72		return &Comparison{left: left, op: OpEq, right: right}
73	}
74	
75	// Ne creates an inequality comparison.
76	func Ne(left, right Expr) *Comparison {
77		return &Comparison{left: left, op: OpNe, right: right}
78	}
79	
80	// Lt creates a less-than comparison.
81	func Lt(left, right Expr) *Comparison {
82		return &Comparison{left: left, op: OpLt, right: right}
83	}
84	
85	// Le creates a less-than-or-equal comparison.
86	func Le(left, right Expr) *Comparison {
87		return &Comparison{left: left, op: OpLe, right: right}
88	}
89	
90	// Gt creates a greater-than comparison.
91	func Gt(left, right Expr) *Comparison {
92		return &Comparison{left: left, op: OpGt, right: right}
93	}
94	
95	// Ge creates a greater-than-or-equal comparison.
96	func Ge(left, right Expr) *Comparison {
97		return &Comparison{left: left, op: OpGe, right: right}
98	}
99	
100	// LogicalOp represents a logical operator.
101	type LogicalOp string
102	
103	const (
104		// OpAnd represents logical AND (&&)
105		OpAnd LogicalOp = "&&"
106		// OpOr represents logical OR (||)
107		OpOr LogicalOp = "||"
108	)
109	
110	// LogicalExpr represents a logical combination of conditions.
111	type LogicalExpr struct {
112		baseCondition
113		op         LogicalOp
114		conditions []Condition
115	}
116	
117	// Op returns the logical operator.
118	func (l *LogicalExpr) Op() LogicalOp { return l.op }
119	
120	// Conditions returns the list of combined conditions.
121	func (l *LogicalExpr) Conditions() []Condition { return l.conditions }
122	
123	// And creates a logical AND of multiple conditions.
124	func And(conditions ...Condition) *LogicalExpr {
125		return &LogicalExpr{
126			op:         OpAnd,
127			conditions: conditions,
128		}
129	}
130	
131	// Or creates a logical OR of multiple conditions.
132	func Or(conditions ...Condition) *LogicalExpr {
133		return &LogicalExpr{
134			op:         OpOr,
135			conditions: conditions,
136		}
137	}
138	
139	// NotExpr represents a logical negation of a condition.
140	type NotExpr struct {
141		baseCondition
142		cond Condition
143	}
144	
145	// Cond returns the negated condition.
146	func (n *NotExpr) Cond() Condition { return n.cond }
147	
148	// Not creates a logical NOT of a condition.
149	func Not(cond Condition) *NotExpr {
150		return &NotExpr{cond: cond}
151	}
152	
153	// IsSetCondition represents a check for whether a parameter is set.
154	type IsSetCondition struct {
155		baseCondition
156		paramName string
157	}
158	
159	// ParamName returns the parameter name being checked.
160	func (i *IsSetCondition) ParamName() string { return i.paramName }
161	
162	// TruthyCondition represents a truthy check on a boolean parameter.
163	// In CUE, this generates `if parameter.name` instead of `if parameter.name == true`.
164	type TruthyCondition struct {
165		baseCondition
166		paramName string
167	}
168	
169	// ParamName returns the parameter name being checked.
170	func (t *TruthyCondition) ParamName() string { return t.paramName }
171	
172	// AndCondition represents a binary logical AND of two conditions.
173	// This is an internal IR type used by cuegen to combine conditions during code generation.
174	// For the user-facing API, use And() which accepts variadic conditions via LogicalExpr.
175	type AndCondition struct {
176		baseCondition
177		left  Condition
178		right Condition
179	}
180	
181	// --- Parameter Runtime Condition Types ---
182	
183	// FalsyCondition represents a falsy check on a boolean parameter.
184	// In CUE, this generates `if !parameter.name`.
185	type FalsyCondition struct {
186		baseCondition
187		paramName string
188	}
189	
190	// ParamName returns the parameter name being checked.
191	func (f *FalsyCondition) ParamName() string { return f.paramName }
192	
193	// InCondition represents a check if a parameter value is in a set of values.
194	// Generates: parameter.name == val1 || parameter.name == val2 || ...
195	type InCondition struct {
196		baseCondition
197		paramName string
198		values    []any
199	}
200	
201	// ParamName returns the parameter name being checked.
202	func (c *InCondition) ParamName() string { return c.paramName }
203	
204	// Values returns the set of values to check against.
205	func (c *InCondition) Values() []any { return c.values }
206	
207	// StringContainsCondition checks if a string parameter contains a substring.
208	// Generates: strings.Contains(parameter.name, "substr")
209	type StringContainsCondition struct {
210		baseCondition
211		paramName string
212		substr    string
213	}
214	
215	// ParamName returns the parameter name being checked.
216	func (c *StringContainsCondition) ParamName() string { return c.paramName }
217	
218	// Substr returns the substring to check for.
219	func (c *StringContainsCondition) Substr() string { return c.substr }
220	
221	// RegexMatchCondition checks if any Value matches a regex pattern.
222	// Generates: <value> =~ "pattern"
223	// Used by both LocalFieldRef.Matches() and StringParam.Matches().
224	type RegexMatchCondition struct {
225		baseCondition
226		source  Value
227		pattern string
228	}
229	
230	// Source returns the value being matched.
231	func (c *RegexMatchCondition) Source() Value { return c.source }
232	
233	// Pattern returns the regex pattern.
234	func (c *RegexMatchCondition) Pattern() string { return c.pattern }
235	
236	// RegexMatch creates a condition that checks if a value matches a regex pattern.
237	func RegexMatch(source Value, pattern string) *RegexMatchCondition {
238		return &RegexMatchCondition{source: source, pattern: pattern}
239	}
240	
