17	package defkit
18	
19	// Render executes the component template with the given test context
20	// and returns the rendered primary output resource.
21	func (c *ComponentDefinition) Render(ctx *TestContextBuilder) *RenderedResource {
22		// Build the runtime context
23		rtCtx := ctx.Build()
24	
25		// Set up the current test context for parameter resolution
26		setCurrentTestContext(rtCtx)
27		defer clearCurrentTestContext()
28	
29		// Create and execute template
30		tpl := NewTemplate()
31		if c.template != nil {
32			c.template(tpl)
33		}
34	
35		// Render the output resource with resolved values
36		return renderResource(tpl.output, rtCtx)
37	}
38	
39	// RenderAll executes the component template and returns all outputs.
40	func (c *ComponentDefinition) RenderAll(ctx *TestContextBuilder) *RenderedOutputs {
41		rtCtx := ctx.Build()
42		setCurrentTestContext(rtCtx)
43		defer clearCurrentTestContext()
44	
45		tpl := NewTemplate()
46		if c.template != nil {
47			c.template(tpl)
48		}
49	
50		outputs := &RenderedOutputs{
51			Primary:   renderResource(tpl.output, rtCtx),
52			Auxiliary: make(map[string]*RenderedResource),
53		}
54	
55		for name, res := range tpl.outputs {
56			// Check if the resource has an output condition
57			if res.outputCondition != nil {
58				if !evaluateCondition(res.outputCondition, rtCtx) {
59					// Condition is false, skip this output
60					continue
61				}
62			}
63			outputs.Auxiliary[name] = renderResource(res, rtCtx)
64		}
65	
66		return outputs
67	}
68	
69	// RenderedOutputs contains all rendered resources from a template.
70	type RenderedOutputs struct {
71		Primary   *RenderedResource
72		Auxiliary map[string]*RenderedResource
73	}
74	
75	// RenderedResource represents a fully rendered Kubernetes resource
76	// with all parameter values resolved.
77	type RenderedResource struct {
78		apiVersion string
79		kind       string
80		data       map[string]any
81	}
82	
83	// APIVersion returns the resource's API version.
84	func (r *RenderedResource) APIVersion() string {
85		if r == nil {
86			return ""
87		}
88		return r.apiVersion
89	}
90	
91	// Kind returns the resource's kind.
92	func (r *RenderedResource) Kind() string {
93		if r == nil {
94			return ""
95		}
96		return r.kind
97	}
98	
99	// Get retrieves a value at the given path (e.g., "spec.replicas").
100	func (r *RenderedResource) Get(path string) any {
101		if r == nil || r.data == nil {
102			return nil
103		}
104		return getNestedValue(r.data, path)
105	}
106	
107	// Data returns the full rendered resource data.
108	func (r *RenderedResource) Data() map[string]any {
109		if r == nil {
110			return nil
111		}
112		return r.data
113	}
114	
115	// renderResource converts a Resource with operations into a RenderedResource
116	// with all values resolved from the test context.
117	func renderResource(res *Resource, ctx *TestRuntimeContext) *RenderedResource {
118		if res == nil {
119			return nil
120		}
121	
122		rendered := &RenderedResource{
123			apiVersion: res.apiVersion,
124			kind:       res.kind,
125			data: map[string]any{
126				"apiVersion": res.apiVersion,
127				"kind":       res.kind,
128				"metadata": map[string]any{
129					"name": ctx.Name(),
130				},
131			},
132		}
133	
134		// Process all operations
135		for _, op := range res.ops {
136			processOp(rendered.data, op, ctx)
137		}
138	
139		return rendered
140	}
141	
142	// processOp processes a single resource operation.
143	func processOp(data map[string]any, op ResourceOp, ctx *TestRuntimeContext) {
144		switch o := op.(type) {
145		case *SetOp:
146			value := resolveValue(o.value, ctx)
147			setNestedValue(data, o.path, value)
148	
149		case *SetIfOp:
150			if evaluateCondition(o.cond, ctx) {
151				value := resolveValue(o.value, ctx)
152				setNestedValue(data, o.path, value)
153			}
154	
155		case *IfBlock:
156			if evaluateCondition(o.cond, ctx) {
157				for _, innerOp := range o.ops {
158					processOp(data, innerOp, ctx)
159				}
160			}
161		}
162	}
163	
164	// resolveValue resolves a Value to its actual value using the test context.
165	func resolveValue(v Value, ctx *TestRuntimeContext) any {
166		if v == nil {
167			return nil
168		}
169	
170		switch val := v.(type) {
171		case *StringParam:
172			return ctx.GetParamOr(val.Name(), val.GetDefault())
173		case *IntParam:
174			return ctx.GetParamOr(val.Name(), val.GetDefault())
175		case *BoolParam:
176			return ctx.GetParamOr(val.Name(), val.GetDefault())
177		case *FloatParam:
178			return ctx.GetParamOr(val.Name(), val.GetDefault())
179		case *ArrayParam:
180			return ctx.GetParamOr(val.Name(), val.GetDefault())
181		case *MapParam:
182			return ctx.GetParamOr(val.Name(), val.GetDefault())
183		case *StructParam:
184			return ctx.GetParamOr(val.Name(), val.GetDefault())
185		case *EnumParam:
186			return ctx.GetParamOr(val.Name(), val.GetDefault())
187		case *ContextRef:
188			return resolveContextRef(val, ctx)
189		case *Literal:
190			return val.Val()
191		case *TransformedValue:
192			// Resolve the source value, then apply the transformation
193			sourceValue := resolveValue(val.source, ctx)
194			if val.transform != nil {
195				return val.transform(sourceValue)
196			}
197			return sourceValue
198		case *CollectionOp:
199			// Resolve source and apply collection operations
200			sourceValue := resolveValue(val.source, ctx)
201			return applyCollectionOps(sourceValue, val.ops)
202		case *MultiSource:
203			// Combine items from multiple fields and apply operations
204			return resolveMultiSource(val, ctx)
205		case *StringKeyMapParam:
206			return ctx.GetParamOr(val.Name(), val.GetDefault())
207		default:
208			// For any Param interface, use method access
209			if p, ok := v.(Param); ok {
210				return ctx.GetParamOr(p.Name(), p.GetDefault())
211			}
212			return v
213		}
214	}
215	
216	// resolveContextRef resolves a context reference to its value.
217	func resolveContextRef(ref *ContextRef, ctx *TestRuntimeContext) any {
218		switch ref.Path() {
219		case "context.name":
220			return ctx.Name()
221		case "context.namespace":
222			return ctx.Namespace()
223		case "context.appName":
224			return ctx.AppName()
225		case "context.appRevision":
226			return ctx.AppRevision()
227		default:
228			return ref.String()
229		}
230	}
231	
232	// evaluateCondition evaluates a Condition using the test context.
233	func evaluateCondition(cond Condition, ctx *TestRuntimeContext) bool {
234		if cond == nil {
235			return true
236		}
237	
238		switch c := cond.(type) {
239		case *IsSetCondition:
