2278	
2279		sb.WriteString("{\n")
2280		for _, key := range sortedKeys(elem.Fields()) {
2281			val := elem.Fields()[key]
2282			valStr := indentMultilineValue(g.valueToCUE(val), innerIndent)
2283			sb.WriteString(fmt.Sprintf("%s%s: %s\n", innerIndent, key, valStr))
2284		}
2285		// Write conditional operations
2286		for _, op := range elem.Ops() {
2287			if setIf, ok := op.(*SetIfOp); ok {
2288				condStr := g.conditionToCUE(setIf.Cond())
2289				valStr := indentMultilineValue(g.valueToCUE(setIf.Value()), innerIndent+"\t")
2290				// Convert dot-separated path to CUE shorthand syntax: "a.b.c" -> "a: b: c"
2291				cuePath := strings.ReplaceAll(setIf.Path(), ".", ": ")
2292				sb.WriteString(fmt.Sprintf("%sif %s {\n", innerIndent, condStr))
2293				sb.WriteString(fmt.Sprintf("%s\t%s: %s\n", innerIndent, cuePath, valStr))
2294				sb.WriteString(fmt.Sprintf("%s}\n", innerIndent))
2295			}
2296		}
2297		// Write patchKey-annotated fields (nested patchKey inside array elements)
2298		for _, pkf := range elem.PatchKeyFields() {
2299			sb.WriteString(fmt.Sprintf("%s// +patchKey=%s\n", innerIndent, pkf.key))
2300			valStr := indentMultilineValue(g.valueToCUEAtDepth(pkf.value, depth+1), innerIndent)
2301			sb.WriteString(fmt.Sprintf("%s%s: %s\n", innerIndent, pkf.field, valStr))
2302		}
2303		sb.WriteString(fmt.Sprintf("%s}", indent))
2304		return sb.String()
