2307	// indentMultilineValue prepends indent to every line of s after the first.
2308	// This is needed when embedding a multi-line valueToCUE result into an
2309	// already-indented context: the first line sits on the same line as the
2310	// key, but subsequent lines need the surrounding indentation added.
2311	func indentMultilineValue(s, indent string) string {
2312		if !strings.Contains(s, "\n") {
2313			return s
2314		}
2315		lines := strings.Split(s, "\n")
2316		for i := 1; i < len(lines); i++ {
2317			if lines[i] != "" {
2318				lines[i] = indent + lines[i]
2319			}
2320		}
2321		return strings.Join(lines, "\n")
2322	}
