1675	func (g *CUEGenerator) writeFieldTree(sb *strings.Builder, node *fieldNode, depth int) {
1676		indent := strings.Repeat(g.indent, depth)
1677	
1678		// Lift child conditions to the parent field when all children share the same
1679		// condition and the parent has no own value/spread/foreach/patchKey. This avoids
1680		// emitting empty parent structs like `foo: { if cond { bar: ... } }`.
1681		g.liftChildConditions(node)
1682	
1683		// Write spread entries FIRST (user labels spread before OAM labels)
1684		// This matches the KubeVela convention of spreading user-provided values
1685		// before adding fixed OAM labels, so user values can be overridden if needed.
1686		for _, spread := range node.spreads {
1687			condStr := g.conditionToCUE(spread.cond)
1688			valStr := g.valueToCUE(spread.value)
1689			sb.WriteString(fmt.Sprintf("%sif %s {\n", indent, condStr))
1690			sb.WriteString(fmt.Sprintf("%s\t%s\n", indent, valStr))
1691			sb.WriteString(fmt.Sprintf("%s}\n", indent))
1692		}
1693	
1694		// Group fields by their condition for cleaner output
1695		unconditional := make([]string, 0)
1696		conditional := make(map[string][]string) // condition string -> field names
1697	
1698		for _, name := range node.childOrder {
1699			child := node.children[name]
1700			switch {
1701			case len(child.condValues) > 0:
1702				// Multi-conditional nodes render their own if blocks internally,
1703				// so they must be treated as unconditional at the parent level.
1704				unconditional = append(unconditional, name)
1705			case child.cond != nil:
1706				condStr := g.conditionToCUE(child.cond)
1707				conditional[condStr] = append(conditional[condStr], name)
1708			default:
1709				unconditional = append(unconditional, name)
1710			}
1711		}
1712	
1713		// Write unconditional fields
1714		for _, name := range unconditional {
1715			child := node.children[name]
1716			g.writeFieldNode(sb, name, child, depth)
1717		}
1718	
1719		// Write conditional fields grouped by condition
1720		for _, condStr := range sortedKeys(conditional) {
1721			fieldNames := conditional[condStr]
1722			sb.WriteString(fmt.Sprintf("%sif %s {\n", indent, condStr))
1723			for _, name := range fieldNames {
1724				child := node.children[name]
1725				// Clear condition since we're inside the if block
1726				childCopy := *child
1727				childCopy.cond = nil
1728				g.writeFieldNode(sb, name, &childCopy, depth+1)
1729			}
1730			sb.WriteString(fmt.Sprintf("%s}\n", indent))
1731		}
1732	}
