1734	// liftChildConditions promotes a shared child condition to the parent node.
1735	// It recursively processes the tree so inner nodes are normalized before parent rendering.
1736	func (g *CUEGenerator) liftChildConditions(node *fieldNode) {
1737		for _, name := range node.childOrder {
1738			child := node.children[name]
1739			if child == nil {
1740				continue
1741			}
1742			// Recurse first so deeper nodes are normalized
1743			g.liftChildConditions(child)
1744	
1745			if child.cond != nil {
1746				continue
1747			}
1748			if child.value != nil || child.isArray || len(child.spreads) > 0 || child.forEach != nil || child.patchKey != nil {
1749				continue
1750			}
1751			if len(child.children) == 0 {
1752				continue
1753			}
1754	
1755			var sharedCond Condition
1756			var sharedCondStr string
1757			canLift := true
1758			for _, grandName := range child.childOrder {
1759				grand := child.children[grandName]
1760				if grand == nil || grand.cond == nil {
1761					canLift = false
1762					break
1763				}
1764				// Don't lift if any grandchild has multiple conditional values,
1765				// since those nodes manage their own condition rendering.
1766				if len(grand.condValues) > 0 {
1767					canLift = false
1768					break
1769				}
1770				condStr := g.conditionToCUE(grand.cond)
1771				if sharedCondStr == "" {
1772					sharedCondStr = condStr
1773					sharedCond = grand.cond
1774				} else if sharedCondStr != condStr {
1775					canLift = false
1776					break
1777				}
1778			}
1779			if canLift && sharedCond != nil {
1780				child.cond = sharedCond
1781				for _, grandName := range child.childOrder {
1782					grand := child.children[grandName]
1783					if grand != nil {
1784						grand.cond = nil
1785					}
1786				}
1787			}
1788		}
